            case 1 -> new Rules(1, 2, NONE, 0, false, true);
            case 2 -> new Rules(2, 4, BOUNCE, 0, false, true);
            case 3 -> new Rules(3, 4, CUTOUT, 1, false, true);
            case 4 -> new Rules(4, 4, CUTOUT, 1, true, true);
