final class Game {
    public final Rules rules;
    public final Track track;
    public final Drone[] drones;
    public int turn;
    public Vec3[] cellPos = new Vec3[0];
    public int[] cellType = new int[0], cellTimer = new int[0];
    public double[][] pylons = new double[0][];

    public Game(Rules rules, int players, long seed) {
        this.rules = rules;
        Rng rng = new Rng(seed);
        track = Track.generate(rng, rules.league() >= 3, rules.margin(), rules.spacing());
        int[] slot = new int[players];
        for (int i = 0; i < players; i++) slot[i] = i;
        for (int i = players - 1; i > 0; i--) {
            int j = rng.nextInt(i + 1);
            int t = slot[i]; slot[i] = slot[j]; slot[j] = t;
        }
        Vec3 g0 = track.c[0], g1 = track.c[1];
        double dx = g0.x() - g1.x(), dy = g0.y() - g1.y(), rad = Math.hypot(dx, dy), base = Math.atan2(dy, dx);
        double spacing = Rules.START_SPACING;
        while (spacing > 0 && !startFits(g1, rad, base, players, spacing)) spacing = Math.max(0, spacing - 50);
        drones = new Drone[players];
        for (int i = 0; i < players; i++) {
            double a = base + (slot[i] - (players - 1) / 2.0) * spacing / rad;
            Vec3 p = new Vec3(g1.x() + rad * Math.cos(a), g1.y() + rad * Math.sin(a), Rules.RADIUS).round(100);
            Vec3 f = new Vec3(g1.x() - p.x(), g1.y() - p.y(), 0).norm().round(1e6);
            drones[i] = new Drone(i, p, f);
            drones[i].slot = slot[i];
            drones[i].boosts = rules.boosts();
            if (rules.collisions() != Rules.NONE) drones[i].ghost = Rules.START_GHOST;
        }
        if (rules.cells()) placeCells(rng);
        if (rules.pylons()) placePylons(rng);
    }

    private void placePylons(Rng rng) {
        int n = track.size();
        int want = 2 + rng.nextInt(3);
        List<double[]> out = new ArrayList<>();
        for (int attempt = 0; attempt < 200 && out.size() < want; attempt++) {
            int leg = rng.nextInt(n);
            Vec3 a = track.c[leg], b = track.c[(leg + 1) % n];
            double hx = b.x() - a.x(), hy = b.y() - a.y(), hl = Math.hypot(hx, hy);
            if (hl < Rules.PYLON_MIN_LEG) continue;
            double t = rng.range(35, 65) / 100.0, off = rng.range(-500, 500), r = Math.round(rng.range(Rules.PYLON_MIN_R, Rules.PYLON_MAX_R));
            double x = Math.round(a.x() + hx * t - hy / hl * off), y = Math.round(a.y() + hy * t + hx / hl * off);
            if (pylonFits(x, y, r, out)) out.add(new double[]{x, y, r});
        }
        pylons = out.toArray(new double[0][]);
    }

    private boolean pylonFits(double x, double y, double r, List<double[]> placed) {
        double m = Rules.PYLON_WALL + r;
        if (x < m || x > Rules.X - m || y < m || y > Rules.Y - m) return false;
        for (Vec3 c : track.c) if (Math.hypot(c.x() - x, c.y() - y) < Rules.PYLON_GATE_CLEAR + r) return false;
        if (Math.hypot(Rules.TRIM_X - x, Rules.TRIM_Y - y) < Rules.TRIM_R + r + 1000) return false;
        for (Drone d : drones) if (Math.hypot(d.p.x() - x, d.p.y() - y) < Rules.PYLON_START_CLEAR + r) return false;
        for (Vec3 c : cellPos) if (Math.hypot(c.x() - x, c.y() - y) < Rules.CELL_PICK + Rules.RADIUS + r) return false;
        for (double[] q : placed) if (Math.hypot(q[0] - x, q[1] - y) < q[2] + r + 1500) return false;
        return true;
    }

    private void placeCells(Rng rng) {
        int n = track.size();
        int[] legs = new int[n];
        for (int i = 0; i < n; i++) legs[i] = i;
        for (int i = n - 1; i > 0; i--) {
            int j = rng.nextInt(i + 1);
            int t = legs[i]; legs[i] = legs[j]; legs[j] = t;
        }
        List<Vec3> pos = new ArrayList<>();
        for (int k = 0; k < n && pos.size() < 3; k++) {
            Vec3 a = track.c[legs[k]], b = track.c[(legs[k] + 1) % n];
            Vec3 d = new Vec3(b.x() - a.x(), b.y() - a.y(), 0);
            if (d.len() < 2500) continue;
            d = d.norm();
            Vec3 mid = a.add(b).mul(0.5);
            double off = rng.range(800, 1400) * (rng.nextInt(2) == 0 ? 1 : -1);
            double z = mid.z() + rng.range(-300, 300);
            double x = mid.x() - d.y() * off, y = mid.y() + d.x() * off;
            pos.add(new Vec3(Math.max(800, Math.min(Rules.X - 800, x)), Math.max(800, Math.min(Rules.Y - 800, y)),
                    Math.max(500, Math.min(4200, z))).round(1));
        }
        cellPos = pos.toArray(new Vec3[0]);
        cellType = new int[cellPos.length];
        cellTimer = new int[cellPos.length];
        for (int i = 0; i < cellType.length; i++) cellType[i] = i;
    }

    private static boolean startFits(Vec3 g1, double rad, double base, int players, double spacing) {
        for (int k = 0; k < players; k++) {
            double a = base + (k - (players - 1) / 2.0) * spacing / rad;
            double x = g1.x() + rad * Math.cos(a), y = g1.y() + rad * Math.sin(a);
            if (x < 500 || x > Rules.X - 500 || y < 500 || y > Rules.Y - 500) return false;
        }
        return true;
    }

    public Game(Rules rules, Track track, Drone[] drones) {
        this.rules = rules;
        this.track = track;
        this.drones = drones;
    }

    public boolean over() {
        if (turn >= Rules.MAX_TURNS) return true;
        int flying = 0;
        Drone last = null;
        for (Drone d : drones) {
            if (d.state == Drone.FINISHED) return true;
            if (d.active()) { flying++; last = d; }
        }
        if (flying == 0) return true;
        if (flying > 1 || drones.length < 2) return false;
        for (Drone d : drones) if (d != last && d.gatesCleared >= last.gatesCleared) return false;
        return true;
    }

    public void step(Command[] cmds) {
        turn++;
        events.clear();
        for (int i = 0; i < cellTimer.length; i++) if (cellTimer[i] > 0) cellTimer[i]--;
        for (Drone d : drones) {
            if (!d.active()) continue;
            Command c = cmds[d.id];
            if (d.mode == 0) d.mode = c.mode();
            if (c.cam() >= 0) d.cam = c.cam();
            orthonormalize(d);
            if (d.cutout > 0 && d.p.z() - Rules.RADIUS <= Rules.RESTART_HEIGHT) d.cutout = 0;
            d.motorsOff = d.cutout > 0 || d.battery <= 0;
            double thrust = 0;
            if (d.motorsOff) {
                d.w = Vec3.ZERO;
                if (d.cutout > 0) d.cutout--;
            } else {
                if (d.mode == Command.ACRO) acro(d, c);
                else angle(d, c);
                thrust = c.throttle() / 100.0 * Rules.THRUST;
                if (c.use() && d.item != 0) {
                    if (d.item == Rules.SHIELD) d.shield = Rules.SHIELD_TURNS;
                    else d.ghost = Rules.GHOST_TURNS;
                    d.item = 0;
                }
                if (c.boost() && d.boosts > 0) {
                    d.v = d.v.add(d.u.mul(Rules.BOOST));
                    d.lastBoostTurn = turn;
                    if (d.boosts == rules.boosts()) d.boostTimer = Rules.BOOST_RECHARGE;
                    d.boosts--;
                }
            }
            d.v = d.v.add(d.u.mul(thrust)).add(new Vec3(0, 0, -Rules.G));
        }
        int[] cleared = new int[drones.length];
        pickT = new double[cellPos.length];
        java.util.Arrays.fill(pickT, Double.MAX_VALUE);
        pickBy = new boolean[cellPos.length][drones.length];
        move(cleared);
        for (Drone d : drones) d.draft = rules.draft() && d.active() && drafting(d);
        for (Drone d : drones) {
            if (!d.active() && d.endTurn != turn) continue;
            if (d.state == Drone.DESTROYED) continue;
            d.v = d.v.mul(d.draft ? Rules.DRAFT_DRAG : Rules.DRAG).round(100);
            d.p = d.p.round(100);
            d.f = d.f.round(1e6);
            d.u = d.u.round(1e6);
            d.w = d.w.round(1e6);
            if (d.boosts < rules.boosts() && --d.boostTimer <= 0) {
                d.boosts++;
                d.boostTimer = d.boosts < rules.boosts() ? Rules.BOOST_RECHARGE : 0;
            }
            d.battery = cleared[d.id] > 0 ? Rules.BATTERY : Math.max(0, d.battery - 1);
            if (d.shield > 0) d.shield--;
            if (d.ghost > 0) d.ghost--;
        }
        for (int k = 0; k < cellPos.length; k++) {
            if (pickT[k] == Double.MAX_VALUE) continue;
            cellTimer[k] = Rules.CELL_RESPAWN;
            for (Drone d : drones) {
                if (!pickBy[k][d.id] || d.state == Drone.DESTROYED) continue;
                if (cellType[k] == Rules.CHARGE) {
                    d.boosts++;
                    d.lastCellCharge = turn;
                    if (d.boosts >= rules.boosts()) d.boostTimer = 0;
                } else if (d.item == 0) d.item = cellType[k];
            }
        }
        if (over()) for (Drone d : drones) if (d.active()) d.endDist = distNext(d);
    }

    private boolean drafting(Drone d) {
        for (Drone o : drones) {
            if (o == d || !o.active()) continue;
            double sp = o.v.len();
            if (sp < 100) continue;
            Vec3 back = o.v.mul(-1 / sp), rel = d.p.sub(o.p);
            double along = rel.dot(back);
            if (along <= 0 || along > Rules.DRAFT_LEN) continue;
            if (rel.sub(back.mul(along)).len() <= Rules.DRAFT_W) return true;
        }
        return false;
    }

    private static void orthonormalize(Drone d) {
        d.f = d.f.norm();
        d.u = d.u.sub(d.f.mul(d.u.dot(d.f))).norm();
    }

    private static void spin(Drone d, Vec3 w) {
        double a = w.len();
        if (a == 0) return;
        Vec3 k = w.mul(1 / a);
        d.f = d.f.rot(k, a);
        d.u = d.u.rot(k, a);
    }

    private static void acro(Drone d, Command c) {
        Vec3 r = d.f.cross(d.u);
        Vec3 w = r.mul(-c.pitch() / 100.0 * Rules.ACRO_RATE)
                .add(d.f.mul(c.roll() / 100.0 * Rules.ACRO_RATE))
                .add(d.u.mul(-c.yaw() / 100.0 * Rules.ACRO_RATE));
        d.w = d.w.add(w.sub(d.w).mul(Rules.SPIN_UP));
        spin(d, d.w);
    }

    private static void angle(Drone d, Command c) {
        Vec3 hf = new Vec3(d.f.x(), d.f.y(), 0);
        if (hf.len() < 1e-6) hf = new Vec3(d.u.x(), d.u.y(), 0).mul(d.f.z() > 0 ? -1 : 1);
        double psi = hf.len() < 1e-6 ? 0 : Math.atan2(hf.y(), hf.x());
        psi -= c.yaw() / 100.0 * Rules.ANGLE_YAW;
        Vec3 f0 = new Vec3(Math.cos(psi), Math.sin(psi), 0), u0 = Vec3.UP, r0 = f0.cross(u0);
        double th = c.pitch() / 100.0 * Rules.MAX_TILT, ph = c.roll() / 100.0 * Rules.MAX_TILT;
        Vec3 f1 = f0.mul(Math.cos(th)).sub(u0.mul(Math.sin(th)));
        Vec3 u1 = u0.mul(Math.cos(th)).add(f0.mul(Math.sin(th)));
        Vec3 u2 = u1.mul(Math.cos(ph)).add(r0.mul(Math.sin(ph)));
        double[] qc = quat(d.f, d.u), qt = quat(f1, u2);
        double w = qt[0] * qc[0] + qt[1] * qc[1] + qt[2] * qc[2] + qt[3] * qc[3];
        double x = -qt[0] * qc[1] + qt[1] * qc[0] - qt[2] * qc[3] + qt[3] * qc[2];
        double y = -qt[0] * qc[2] + qt[1] * qc[3] + qt[2] * qc[0] - qt[3] * qc[1];
        double z = -qt[0] * qc[3] - qt[1] * qc[2] + qt[2] * qc[1] + qt[3] * qc[0];
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
        double s = Math.sqrt(x * x + y * y + z * z);
        double a = 2 * Math.atan2(s, w);
        double acc = Rules.SPIN_UP * Rules.ACRO_RATE;
        double want = Math.min(Math.min(Rules.SLEW, Math.sqrt(2 * acc * a)), a);
        Vec3 wd = s == 0 ? Vec3.ZERO : new Vec3(x, y, z).mul(want / s);
        Vec3 dw = wd.sub(d.w);
        if (dw.len() > acc) dw = dw.mul(acc / dw.len());
        d.w = d.w.add(dw);
        spin(d, d.w);
    }

    private static double[] quat(Vec3 f, Vec3 u) {
        Vec3 l = u.cross(f);
        double m00 = f.x(), m01 = l.x(), m02 = u.x(), m10 = f.y(), m11 = l.y(), m12 = u.y(), m20 = f.z(), m21 = l.z(), m22 = u.z();
        double tr = m00 + m11 + m22, s;
        if (tr > 0) {
            s = Math.sqrt(tr + 1) * 2;
            return new double[]{s / 4, (m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s};
        } else if (m00 > m11 && m00 > m22) {
            s = Math.sqrt(1 + m00 - m11 - m22) * 2;
            return new double[]{(m21 - m12) / s, s / 4, (m01 + m10) / s, (m02 + m20) / s};
        } else if (m11 > m22) {
            s = Math.sqrt(1 + m11 - m00 - m22) * 2;
            return new double[]{(m02 - m20) / s, (m01 + m10) / s, s / 4, (m12 + m21) / s};
        } else {
            s = Math.sqrt(1 + m22 - m00 - m11) * 2;
            return new double[]{(m10 - m01) / s, (m02 + m20) / s, (m12 + m21) / s, s / 4};
        }
    }

    private void move(int[] cleared) {
        double t = 0;
        double R = Rules.RADIUS;
        for (int guard = 0; t < 1 && guard < 64; guard++) {
            double best = 1 - t;
            int type = -1, a = -1, b = -1;
            for (Drone d : drones) {
                if (!d.active()) continue;
                double[] tt = {
                        d.v.z() < 0 ? (d.p.z() - R) / -d.v.z() : 2,
                        d.v.x() < 0 ? (d.p.x() - R) / -d.v.x() : d.v.x() > 0 ? (Rules.X - R - d.p.x()) / d.v.x() : 2,
                        d.v.y() < 0 ? (d.p.y() - R) / -d.v.y() : d.v.y() > 0 ? (Rules.Y - R - d.p.y()) / d.v.y() : 2,
                        d.v.z() > 0 ? (Rules.Z - R - d.p.z()) / d.v.z() : 2};
                for (int k = 0; k < 4; k++) {
                    double x = Math.max(0, tt[k]);
                    if (x < best) { best = x; type = k; a = d.id; }
                }
            }
            for (Drone d : drones) {
                if (!d.active()) continue;
                for (int k = 0; k < pylons.length; k++) {
                    double qx = d.p.x() - pylons[k][0], qy = d.p.y() - pylons[k][1], vx = d.v.x(), vy = d.v.y();
                    double bq = qx * vx + qy * vy;
                    if (bq >= 0) continue;
                    double rr = pylons[k][2] + R, aq = vx * vx + vy * vy, cq = qx * qx + qy * qy - rr * rr, x;
                    if (cq <= 0) x = 0;
                    else {
                        double disc = bq * bq - aq * cq;
                        if (disc < 0) continue;
                        x = (-bq - Math.sqrt(disc)) / aq;
                    }
                    if (x < best) { best = x; type = 5; a = d.id; b = k; }
                }
            }
            if (rules.collisions() != Rules.NONE) {
                for (int i = 0; i < drones.length; i++) {
                    if (!drones[i].active()) continue;
                    if (drones[i].ghost > 0) continue;
                    for (int j = i + 1; j < drones.length; j++) {
                        if (!drones[j].active() || drones[j].ghost > 0) continue;
                        Vec3 dp = drones[j].p.sub(drones[i].p), dv = drones[j].v.sub(drones[i].v);
                        double bq = dp.dot(dv);
                        if (bq >= 0) continue;
                        double aq = dv.dot(dv), cq = dp.dot(dp) - 4 * R * R, x;
                        if (cq <= 0) x = 0;
                        else {
                            double disc = bq * bq - aq * cq;
                            if (disc < 0) continue;
                            x = (-bq - Math.sqrt(disc)) / aq;
                        }
                        if (x < best) { best = x; type = 4; a = i; b = j; }
                    }
                }
            }
            for (Drone d : drones) {
                if (!d.active()) continue;
                Vec3 p0 = d.p;
                d.p = d.p.add(d.v.mul(best));
                gate(d, p0, cleared);
                trim(d, p0);
                pick(d, p0, t, best);
            }
            t += best;
            if (type < 0) break;
            if (type == 4) collide(drones[a], drones[b], t);
            else if (type == 5) pylon(drones[a], pylons[b], t);
            else if (type == 0) floor(drones[a]);
            else wall(drones[a], type);
        }
    }

    private void pylon(Drone d, double[] q, double at) {
        Vec3 n = new Vec3(d.p.x() - q[0], d.p.y() - q[1], 0).norm();
        double s = -d.v.dot(n);
        d.v = d.v.add(n.mul(2 * s));
        boolean crash = rules.collisions() == Rules.CUTOUT && s >= Rules.CUTOUT_SPEED && d.shield == 0;
        if (crash) {
            d.cutout = Rules.CUTOUT_TURNS;
            d.cutouts++;
        }
        Vec3 c = new Vec3(q[0], q[1], d.p.z()).add(n.mul(q[2]));
        events.add(new double[]{d.id, -1, at, d.p.x(), d.p.y(), d.p.z(), c.x(), c.y(), c.z(), s, crash ? 1 : 0});
    }

    private void floor(Drone d) {
        d.p = new Vec3(d.p.x(), d.p.y(), Rules.RADIUS);
        if (d.motorsOff || d.cutout > 0 || -d.v.z() > Rules.LAND_SPEED) {
            d.state = Drone.DESTROYED;
            d.endTurn = turn;
            d.endDist = distNext(d);
            d.v = Vec3.ZERO;
        } else d.v = new Vec3(d.v.x(), d.v.y(), 0);
    }

    private static void wall(Drone d, int type) {
        if (type == 1) d.v = new Vec3(-d.v.x(), d.v.y(), d.v.z());
        else if (type == 2) d.v = new Vec3(d.v.x(), -d.v.y(), d.v.z());
        else d.v = new Vec3(d.v.x(), d.v.y(), -d.v.z());
    }

    public final List<double[]> events = new ArrayList<>();

    private void collide(Drone a, Drone b, double at) {
        Vec3 pa = a.p, pb = b.p;
        Vec3 n = b.p.sub(a.p).norm();
        double s = a.v.sub(b.v).dot(n);
        a.v = a.v.sub(n.mul(s));
        b.v = b.v.add(n.mul(s));
        if (rules.collisions() == Rules.CUTOUT && s >= Rules.CUTOUT_SPEED && a.shield == 0 && b.shield == 0) {
            a.cutout = Rules.CUTOUT_TURNS;
            b.cutout = Rules.CUTOUT_TURNS;
            a.cutouts++;
            b.cutouts++;
        }
        events.add(new double[]{a.id, b.id, at, pa.x(), pa.y(), pa.z(), pb.x(), pb.y(), pb.z(), s, a.cutout == Rules.CUTOUT_TURNS && b.cutout == Rules.CUTOUT_TURNS ? 1 : 0});
    }

    private void gate(Drone d, Vec3 p0, int[] cleared) {
        int g = d.nextGate;
        Vec3 c = track.c[g], n = track.n[g];
        double d0 = n.dot(p0.sub(c)), d1 = n.dot(d.p.sub(c));
        if (!(d0 < 0 && d1 >= 0)) return;
        Vec3 x = p0.add(d.p.sub(p0).mul(d0 / (d0 - d1)));
        if (x.sub(c).len() >= rules.clearR()) return;
        cleared[d.id]++;
        d.gatesCleared++;
        d.nextGate = (g + 1) % track.size();
        if (g == 0 && ++d.lap == Rules.LAPS) {
            d.state = Drone.FINISHED;
            d.endTurn = turn;
        }
    }

    private void trim(Drone d, Vec3 p0) {
        if (d.trimTurn >= 0) return;
        Vec3 c = new Vec3(Rules.TRIM_X, Rules.TRIM_Y, Rules.TRIM_Z), n = new Vec3(1, 1, 0).norm();
        double d0 = n.dot(p0.sub(c)), d1 = n.dot(d.p.sub(c));
        if (d0 == d1 || (d0 < 0) == (d1 < 0)) return;
        Vec3 x = p0.add(d.p.sub(p0).mul(d0 / (d0 - d1)));
        if (x.sub(c).len() < Rules.TRIM_R - Rules.RADIUS) d.trimTurn = turn;
    }

    private double[] pickT;
    private boolean[][] pickBy;

    private void pick(Drone d, Vec3 p0, double t0, double dt) {
        Vec3 seg = d.p.sub(p0);
        double l2 = seg.dot(seg);
        for (int k = 0; k < cellPos.length; k++) {
            if (cellTimer[k] > 0 || (cellType[k] != Rules.CHARGE && d.item != 0)) continue;
            double s = l2 == 0 ? 0 : Math.max(0, Math.min(1, cellPos[k].sub(p0).dot(seg) / l2));
            if (p0.add(seg.mul(s)).sub(cellPos[k]).len() > Rules.CELL_PICK) continue;
            double at = t0 + s * dt;
            if (at < pickT[k]) {
                pickT[k] = at;
                java.util.Arrays.fill(pickBy[k], false);
            }
            if (at == pickT[k]) pickBy[k][d.id] = true;
        }
    }

    public double distNext(Drone d) { return d.p.sub(track.c[d.nextGate]).len(); }

    public int[] positions() {
        long[] k = new long[drones.length];
        for (Drone d : drones) {
            if (d.state == Drone.FINISHED) k[d.id] = 1_000_000_000_000L - d.endTurn;
            else k[d.id] = d.gatesCleared * 100_000_000L - Math.round(Math.min(d.active() ? distNext(d) : d.endDist, 99_999_999));
        }
        int[] pos = new int[drones.length];
        for (int i = 0; i < k.length; i++) {
            pos[i] = 1;
            for (long x : k) if (x > k[i]) pos[i]++;
        }
        return pos;
    }

    public long[] rankKeys() {
        long[] k = new long[drones.length];
        for (Drone d : drones) {
            if (d.state == Drone.FINISHED) k[d.id] = 1_000_000_000_000L - d.endTurn;
            else k[d.id] = d.gatesCleared * 100_000_000L - Math.round(Math.min(d.endDist, 99_999_999));
        }
        return k;
    }

    public List<String> initLines(int id) {
        List<String> out = new ArrayList<>();
        out.add(drones.length + " " + id + " " + Rules.LAPS + " " + track.size());
        for (int g = 0; g < track.size(); g++) {
            Vec3 c = track.c[g], n = track.n[g];
            out.add(String.format(Locale.ROOT, "%.0f %.0f %.0f %.6f %.6f %.6f %.0f", c.x(), c.y(), c.z(), n.x(), n.y(), n.z(), rules.gateR()));
        }
        out.add(String.valueOf(cellPos.length));
        for (int k = 0; k < cellPos.length; k++)
            out.add(String.format(Locale.ROOT, "%.0f %.0f %.0f %s", cellPos[k].x(), cellPos[k].y(), cellPos[k].z(), new String[]{"CHARGE", "SHIELD", "GHOST"}[cellType[k]]));
        out.add(String.valueOf(pylons.length));
        for (double[] q : pylons) out.add(String.format(Locale.ROOT, "%.0f %.0f %.0f", q[0], q[1], q[2]));
        return out;
    }

    public List<String> turnLines() {
        List<String> out = new ArrayList<>();
        for (Drone d : drones) {
            out.add(String.format(Locale.ROOT, "%.2f %.2f %.2f %.2f %.2f %.2f %.6f %.6f %.6f %.6f %.6f %.6f %d %d %d %d %d %d %d %d %d %d %.6f %.6f %.6f",
                    d.p.x(), d.p.y(), d.p.z(), d.v.x(), d.v.y(), d.v.z(), d.f.x(), d.f.y(), d.f.z(), d.u.x(), d.u.y(), d.u.z(),
                    d.nextGate, d.lap, d.boosts, d.boostTimer, d.battery, d.cutout, d.state, d.shield, d.ghost, d.item,
                    d.w.x(), d.w.y(), d.w.z()));
        }
        for (int t : cellTimer) out.add(String.valueOf(t));
        return out;
    }
}

interface Bot {
    void init(List<String> lines);

    String turn(List<String> lines);
}

final class Greedy implements Bot {
    final double cruise, gain, lead, cap;
    int me, gates;
    double[][] gc, gn;
    boolean first = true;

    public Greedy(double cruise, double gain, double lead, double cap) { this.cruise = cruise; this.gain = gain; this.lead = lead; this.cap = cap; }

    public Greedy(double cruise, double gain, double lead) { this(cruise, gain, lead, 1); }

    public Greedy() { this(450, 0.3, 0.5); }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        me = Integer.parseInt(h[1]);
        gates = Integer.parseInt(h[3]);
        gc = new double[gates][];
        gn = new double[gates][];
        for (int g = 0; g < gates; g++) {
            double[] t = nums(lines.get(1 + g));
            gc[g] = new double[]{t[0], t[1], t[2]};
            gn[g] = new double[]{t[3], t[4], t[5]};
        }
    }

    public String turn(List<String> lines) {
        double[] s = nums(lines.get(me));
        int[] k = control(new double[]{s[0], s[1], s[2]}, new double[]{s[3], s[4], s[5]}, new double[]{s[6], s[7], s[8]},
                gc[(int) s[12]], gn[(int) s[12]], cruise, gain, lead);
        k[0] = (int) Math.round(Math.min(k[0], 100 * cap));
        String cmd = k[0] + " " + k[1] + " " + k[2] + " " + k[3];
        if (first) { first = false; return "ANGLE " + cmd; }
        return cmd;
    }

    static int[] control(double[] p, double[] v, double[] f, double[] c, double[] n, double cruise, double gain, double lead) {
        double along = dot(sub(p, c), n);
        double[] lat = sub(sub(p, c), mul(n, along));
        double latLen = len(lat);
        boolean cone = along < 0 && latLen < -along * 1.2 + 300;
        double[] aim = cone ? add(c, mul(n, along * lead + 200))
                : add(add(c, mul(n, -Math.max(1200, latLen))), mul(norm(lat), Math.min(latLen, 700)));
        double dist = len(sub(aim, p));
        double speed = cone ? cruise : Math.min(cruise, Math.sqrt(2 * 25 * dist) + 60);
        double[] dir = norm(sub(aim, p));
        double[] vd = mul(dir, speed);
        double floorV = -(p[2] - 300) * 0.25;
        if (vd[2] < floorV) vd[2] = floorV;
        double[] a = mul(sub(vd, v), gain);
        a[2] += 20;
        if (a[2] < 1) a[2] = 1;
        double h = Math.hypot(a[0], a[1]);
        double tilt = Math.toRadians(59);
        if (h > a[2] * Math.tan(tilt)) { double k = a[2] * Math.tan(tilt) / h; a[0] *= k; a[1] *= k; }
        int throttle = clamp((int) Math.round(len(a) / 50 * 100), 0, 100);
        double psi = Math.atan2(f[1], f[0]);
        double want = Math.atan2(dir[1], dir[0]);
        double err = Math.atan2(Math.sin(psi - want), Math.cos(psi - want));
        int yaw = clamp((int) Math.round(err / Math.toRadians(30) * 100), -100, 100);
        double npsi = psi - yaw / 100.0 * Math.toRadians(30);
        double[] f0 = {Math.cos(npsi), Math.sin(npsi), 0}, r0 = {Math.sin(npsi), -Math.cos(npsi), 0};
        double[] t = norm(a);
        double ph = Math.asin(Math.max(-1, Math.min(1, dot(t, r0))));
        double th = Math.atan2(dot(t, f0), t[2]);
        int pitch = clamp((int) Math.round(Math.toDegrees(th) / 60 * 100), -100, 100);
        int roll = clamp((int) Math.round(Math.toDegrees(ph) / 60 * 100), -100, 100);
        return new int[]{throttle, yaw, pitch, roll};
    }

    static double[] nums(String line) {
        String[] t = line.trim().split(" ");
        double[] r = new double[t.length];
        for (int i = 0; i < t.length; i++) r[i] = Double.parseDouble(t[i]);
        return r;
    }

    static int clamp(int x, int lo, int hi) { return Math.max(lo, Math.min(hi, x)); }
    static double dot(double[] a, double[] b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
    static double[] add(double[] a, double[] b) { return new double[]{a[0] + b[0], a[1] + b[1], a[2] + b[2]}; }
    static double[] sub(double[] a, double[] b) { return new double[]{a[0] - b[0], a[1] - b[1], a[2] - b[2]}; }
    static double[] mul(double[] a, double k) { return new double[]{a[0] * k, a[1] * k, a[2] * k}; }
    static double len(double[] a) { return Math.sqrt(dot(a, a)); }
    static double[] norm(double[] a) { double l = len(a); return l == 0 ? a : mul(a, 1 / l); }

    static double[][] pylons(List<String> lines) {
        int gates = Integer.parseInt(lines.get(0).trim().split(" ")[3]);
        int cells = Integer.parseInt(lines.get(1 + gates).trim());
        int at = 2 + gates + cells;
        if (lines.size() <= at) return new double[0][];
        int n = Integer.parseInt(lines.get(at).trim());
        double[][] out = new double[n][];
        for (int k = 0; k < n; k++) out[k] = nums(lines.get(at + 1 + k));
        return out;
    }
}

final class Planner implements Bot {
    private final int horizon;
    private final double[][] params;
    private int me, laps;
    private Track track;
    private double[][] pylons = new double[0][];
    private boolean first = true;
    private Rules solo = new Rules(1, 1, Rules.CUTOUT, 0, false, false);

    public Planner(int horizon, double[] cruises) {
        this.horizon = horizon;
        double[] gains = {0.3, 0.6}, leads = {0.3, 0.6};
        params = new double[cruises.length * 4][];
        int i = 0;
        for (double c : cruises) for (double g : gains) for (double l : leads) params[i++] = new double[]{c, g, l};
    }

    public Planner() { this(40, new double[]{300, 450, 600}); }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        me = Integer.parseInt(h[1]);
        laps = Integer.parseInt(h[2]);
        int gates = Integer.parseInt(h[3]);
        Vec3[] c = new Vec3[gates], n = new Vec3[gates];
        for (int g = 0; g < gates; g++) {
            double[] t = Greedy.nums(lines.get(1 + g));
            c[g] = new Vec3(t[0], t[1], t[2]);
            n[g] = new Vec3(t[3], t[4], t[5]);
            if (t[6] < Rules.WOOD_GATE_R) solo = new Rules(3, 1, Rules.CUTOUT, solo.boosts(), solo.cells(), false);
        }
        track = new Track(c, n);
        pylons = Greedy.pylons(lines);
    }

    public String turn(List<String> lines) {
        double[] s = Greedy.nums(lines.get(me));
        Drone base = new Drone(0, new Vec3(s[0], s[1], s[2]), new Vec3(s[6], s[7], s[8]));
        base.v = new Vec3(s[3], s[4], s[5]);
        base.u = new Vec3(s[9], s[10], s[11]);
        if (s.length > 24) base.w = new Vec3(s[22], s[23], s[24]);
        base.nextGate = (int) s[12];
        base.lap = (int) s[13];
        base.battery = (int) s[16];
        base.cutout = (int) s[17];
        base.mode = Command.ANGLE;
        double best = Double.NEGATIVE_INFINITY;
        int[] bestCmd = null;
        for (double[] pr : params) {
            Drone d = base.copy(0);
            Game g = new Game(solo, track, new Drone[]{d});
            g.pylons = pylons;
            int[] firstCmd = null;
            Command[] cmds = new Command[1];
            int t = 0;
            for (; t < horizon && d.active(); t++) {
                int[] k = Greedy.control(arr(d.p), arr(d.v), arr(d.f), arr(track.c[d.nextGate]), arr(track.n[d.nextGate]), pr[0], pr[1], pr[2]);
                if (firstCmd == null) firstCmd = k;
                cmds[0] = new Command(Command.ANGLE, k[0], k[1], k[2], k[3], false, "");
                g.step(cmds);
                if (d.lap >= laps) break;
            }
            double score = d.gatesCleared * 1e6 - g.distNext(d);
            if (d.state == Drone.DESTROYED) score -= 1e9;
            if (d.lap >= laps) score += 1e8 - t * 1e4;
            if (score > best) { best = score; bestCmd = firstCmd; }
        }
        String cmd = bestCmd[0] + " " + bestCmd[1] + " " + bestCmd[2] + " " + bestCmd[3];
        if (first) { first = false; return "ANGLE " + cmd; }
        return cmd;
    }

    private static double[] arr(Vec3 v) { return new double[]{v.x(), v.y(), v.z()}; }
}

final class PlannerX implements Bot {
    private static final double BOOST_VALUE = 1000, ITEM_VALUE = 600;
    private final int horizon = 40;
    private final double[][] params;
    private int me, laps, players;
    private Track track;
    private double[][] pylons = new double[0][];
    private Vec3[] cellPos = new Vec3[0];
    private int[] cellType = new int[0];
    private boolean first = true;
    private Rules solo = new Rules(1, 1, Rules.CUTOUT, 9, true, false);

    public PlannerX() {
        double[] cruises = {300, 450, 600}, gains = {0.3, 0.6}, leads = {0.3, 0.6};
        params = new double[12][];
        int i = 0;
        for (double c : cruises) for (double g : gains) for (double l : leads) params[i++] = new double[]{c, g, l};
    }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        players = Integer.parseInt(h[0]);
        me = Integer.parseInt(h[1]);
        laps = Integer.parseInt(h[2]);
        int gates = Integer.parseInt(h[3]);
        Vec3[] c = new Vec3[gates], n = new Vec3[gates];
        for (int g = 0; g < gates; g++) {
            double[] t = Greedy.nums(lines.get(1 + g));
            c[g] = new Vec3(t[0], t[1], t[2]);
            n[g] = new Vec3(t[3], t[4], t[5]);
            if (t[6] < Rules.WOOD_GATE_R) solo = new Rules(3, 1, Rules.CUTOUT, solo.boosts(), solo.cells(), false);
        }
        track = new Track(c, n);
        pylons = Greedy.pylons(lines);
        int cells = Integer.parseInt(lines.get(1 + gates).trim());
        cellPos = new Vec3[cells];
        cellType = new int[cells];
        for (int k = 0; k < cells; k++) {
            String[] t = lines.get(2 + gates + k).trim().split(" ");
            cellPos[k] = new Vec3(Double.parseDouble(t[0]), Double.parseDouble(t[1]), Double.parseDouble(t[2]));
            cellType[k] = t[3].equals("CHARGE") ? Rules.CHARGE : t[3].equals("SHIELD") ? Rules.SHIELD : Rules.GHOST;
        }
    }

    public String turn(List<String> lines) {
        double[] s = Greedy.nums(lines.get(me));
        Drone base = new Drone(0, new Vec3(s[0], s[1], s[2]), new Vec3(s[6], s[7], s[8]));
        base.v = new Vec3(s[3], s[4], s[5]);
        base.u = new Vec3(s[9], s[10], s[11]);
        if (s.length > 24) base.w = new Vec3(s[22], s[23], s[24]);
        base.nextGate = (int) s[12];
        base.lap = (int) s[13];
        base.boosts = (int) s[14];
        base.boostTimer = (int) s[15];
        base.battery = (int) s[16];
        base.cutout = (int) s[17];
        base.item = (int) s[21];
        base.mode = Command.ANGLE;
        int[] timers = new int[cellPos.length];
        for (int k = 0; k < timers.length; k++) timers[k] = Integer.parseInt(lines.get(players + k).trim());

        List<double[]> cands = new ArrayList<>();
        for (double[] pr : params) {
            cands.add(new double[]{pr[0], pr[1], pr[2], 0, -1});
            if (base.boosts > 0) cands.add(new double[]{pr[0], pr[1], pr[2], 1, -1});
        }
        for (int k = 0; k < cellPos.length; k++) {
            if (timers[k] > 0 || (cellType[k] != Rules.CHARGE && base.item != 0)) continue;
            if (cellPos[k].sub(base.p).len() > 5000) continue;
            cands.add(new double[]{450, 0.6, 0.3, 0, k});
            cands.add(new double[]{600, 0.6, 0.3, 0, k});
        }
        double best = Double.NEGATIVE_INFINITY;
        int[] bestCmd = null;
        boolean bestBoost = false;
        for (double[] pr : cands) {
            Drone d = base.copy(0);
            Game g = new Game(solo, track, new Drone[]{d});
            g.pylons = pylons;
            g.cellPos = cellPos;
            g.cellType = cellType;
            g.cellTimer = timers.clone();
            int target = (int) pr[4];
            int[] firstCmd = null;
            Command[] cmds = new Command[1];
            int t = 0;
            for (; t < horizon && d.active(); t++) {
                boolean chase = target >= 0 && g.cellTimer[target] == 0 && t < 30;
                Vec3 c = chase ? cellPos[target] : track.c[d.nextGate];
                Vec3 n = chase ? cellPos[target].sub(d.p).norm() : track.n[d.nextGate];
                int[] k = Greedy.control(arr(d.p), arr(d.v), arr(d.f), arr(c), arr(n), pr[0], pr[1], pr[2]);
                if (firstCmd == null) firstCmd = k;
                cmds[0] = new Command(Command.ANGLE, k[0], k[1], k[2], k[3], t == 0 && pr[3] == 1, "");
                g.step(cmds);
                if (d.lap >= laps) break;
            }
            double score = d.gatesCleared * 1e6 - g.distNext(d) + d.boosts * BOOST_VALUE + (d.item != 0 ? ITEM_VALUE : 0)
                    + (d.shield > 0 || d.ghost > 0 ? ITEM_VALUE : 0);
            if (d.state == Drone.DESTROYED) score -= 1e9;
            if (d.lap >= laps) score += 1e8 - t * 1e4;
            if (score > best) { best = score; bestCmd = firstCmd; bestBoost = pr[3] == 1; }
        }
        boolean use = base.item != 0 && threatened(lines, base);
        String cmd = bestCmd[0] + " " + bestCmd[1] + " " + bestCmd[2] + " " + bestCmd[3] + (bestBoost ? " BOOST" : "") + (use ? " USE" : "");
        if (first) { first = false; return "ANGLE " + cmd + " CAM 35"; }
        return cmd;
    }

    private boolean threatened(List<String> lines, Drone me0) {
        for (int j = 0; j < players; j++) {
            if (j == me) continue;
            double[] o = Greedy.nums(lines.get(j));
            if (o[18] != 1) continue;
            Vec3 op = new Vec3(o[0], o[1], o[2]), ov = new Vec3(o[3], o[4], o[5]);
            Vec3 rel = op.sub(me0.p);
            double closing = -rel.dot(ov.sub(me0.v)) / Math.max(1, rel.len());
            if (rel.len() < 1500 && closing > Rules.CUTOUT_SPEED * 0.6) return true;
        }
        return false;
    }

    private static double[] arr(Vec3 v) { return new double[]{v.x(), v.y(), v.z()}; }
}

final class AcroControl {
    private static final double RATE = Math.toRadians(60);
    private static final double G = 1.2, C = 1.8;

    public static int[] control(Vec3 p, Vec3 v, Vec3 f0, Vec3 u0, Vec3 c, Vec3 n, double cruise, double gain, double lead, double tiltDeg) {
        return control(p, v, f0, u0, Vec3.ZERO, c, n, cruise, gain, lead, tiltDeg);
    }

    public static int[] control(Vec3 p, Vec3 v, Vec3 f0, Vec3 u0, Vec3 w0, Vec3 c, Vec3 n, double cruise, double gain, double lead, double tiltDeg) {
        Vec3 f = f0.norm();
        Vec3 u = u0.sub(f.mul(u0.dot(f))).norm();
        double along = p.sub(c).dot(n);
        Vec3 lat = p.sub(c).sub(n.mul(along));
        double latLen = lat.len();
        boolean cone = along < 0 && latLen < -along * 1.2 + 300;
        Vec3 aim = cone ? c.add(n.mul(along * lead + 200))
                : c.add(n.mul(-Math.max(1200, latLen))).add(lat.norm().mul(Math.min(latLen, 700)));
        double dist = aim.sub(p).len();
        double speed = cone ? cruise : Math.min(cruise, Math.sqrt(2 * 30 * dist) + 60);
        Vec3 dir = aim.sub(p).norm();
        Vec3 vd = dir.mul(speed);
        double floorV = -(p.z() - 350) * 0.25;
        if (vd.z() < floorV) vd = new Vec3(vd.x(), vd.y(), floorV);
        Vec3 a = vd.sub(v).mul(gain);
        double az = Math.max(1, a.z() + 20);
        double h = Math.hypot(a.x(), a.y());
        double limit = az * Math.tan(Math.toRadians(tiltDeg));
        double ax = a.x(), ay = a.y();
        if (h > limit) { ax *= limit / h; ay *= limit / h; }
        Vec3 acc = new Vec3(ax, ay, az);
        Vec3 ut = acc.norm();
        Vec3 heading = new Vec3(dir.x(), dir.y(), 0);
        if (heading.len() < 1e-6) heading = new Vec3(f.x(), f.y(), 0);
        Vec3 ft = heading.sub(ut.mul(heading.dot(ut)));
        if (ft.len() < 1e-6) ft = f.sub(ut.mul(f.dot(ut)));
        ft = ft.norm();
        Vec3 want = rotation(f, u, ft, ut).mul(G);
        if (want.len() > RATE) want = want.mul(RATE / want.len());
        Vec3 w = w0.add(want.sub(w0).mul(C));
        Vec3 r = f.cross(u);
        int pitch = clamp((int) Math.round(-w.dot(r) / RATE * 100));
        int roll = clamp((int) Math.round(w.dot(f) / RATE * 100));
        int yaw = clamp((int) Math.round(-w.dot(u) / RATE * 100));
        double tiltErr = Math.acos(Math.max(-1, Math.min(1, u.dot(ut))));
        double thrust = acc.len() * Math.max(0, Math.cos(tiltErr));
        int throttle = Math.max(0, Math.min(100, (int) Math.round(thrust / 50 * 100)));
        return new int[]{throttle, yaw, pitch, roll};
    }

    private static int clamp(int x) { return Math.max(-100, Math.min(100, x)); }

    static Vec3 rotation(Vec3 f, Vec3 u, Vec3 ft, Vec3 ut) {
        double[] qc = quat(f, u), qt = quat(ft, ut);
        double w = qt[0] * qc[0] + qt[1] * qc[1] + qt[2] * qc[2] + qt[3] * qc[3];
        double x = -qt[0] * qc[1] + qt[1] * qc[0] - qt[2] * qc[3] + qt[3] * qc[2];
        double y = -qt[0] * qc[2] + qt[1] * qc[3] + qt[2] * qc[0] - qt[3] * qc[1];
        double z = -qt[0] * qc[3] - qt[1] * qc[2] + qt[2] * qc[1] + qt[3] * qc[0];
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
        double s = Math.sqrt(x * x + y * y + z * z);
        if (s == 0) return Vec3.ZERO;
        double angle = 2 * Math.atan2(s, w);
        return new Vec3(x, y, z).mul(angle / s);
    }

    static double[] quat(Vec3 f, Vec3 u) {
        Vec3 l = u.cross(f);
        double m00 = f.x(), m01 = l.x(), m02 = u.x(), m10 = f.y(), m11 = l.y(), m12 = u.y(), m20 = f.z(), m21 = l.z(), m22 = u.z();
        double tr = m00 + m11 + m22, s;
        if (tr > 0) {
            s = Math.sqrt(tr + 1) * 2;
            return new double[]{s / 4, (m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s};
        } else if (m00 > m11 && m00 > m22) {
            s = Math.sqrt(1 + m00 - m11 - m22) * 2;
            return new double[]{(m21 - m12) / s, s / 4, (m01 + m10) / s, (m02 + m20) / s};
        } else if (m11 > m22) {
            s = Math.sqrt(1 + m11 - m00 - m22) * 2;
            return new double[]{(m02 - m20) / s, (m01 + m10) / s, s / 4, (m12 + m21) / s};
        } else {
            s = Math.sqrt(1 + m22 - m00 - m11) * 2;
            return new double[]{(m10 - m01) / s, (m02 + m20) / s, (m12 + m21) / s, s / 4};
        }
    }
}

final class AcroPlanner implements Bot {
    private static final double BOOST_VALUE = 1000, ITEM_VALUE = 600;
    private final int horizon;
    private final double[][] params;
    private int me, laps, players;
    private Track track;
    private double[][] pylons = new double[0][];
    private Vec3[] cellPos = new Vec3[0];
    private int[] cellType = new int[0];
    private boolean first = true;
    private final Rules solo = new Rules(3, 1, Rules.CUTOUT, 9, true, false);
    private double[] lastPick;

    public AcroPlanner(int horizon) {
        this.horizon = horizon;
        double[] cruises = {450, 650, 850}, tilts = {60, 72, 80}, leads = {0.3, 0.6};
        params = new double[cruises.length * tilts.length * leads.length][];
        int i = 0;
        for (double c : cruises) for (double t : tilts) for (double l : leads) params[i++] = new double[]{c, 0.4, l, t};
    }

    public AcroPlanner() { this(40); }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        players = Integer.parseInt(h[0]);
        me = Integer.parseInt(h[1]);
        laps = Integer.parseInt(h[2]);
        int gates = Integer.parseInt(h[3]);
        Vec3[] c = new Vec3[gates], n = new Vec3[gates];
        for (int g = 0; g < gates; g++) {
            double[] t = Greedy.nums(lines.get(1 + g));
            c[g] = new Vec3(t[0], t[1], t[2]);
            n[g] = new Vec3(t[3], t[4], t[5]);
        }
        track = new Track(c, n);
        pylons = Greedy.pylons(lines);
        int cells = Integer.parseInt(lines.get(1 + gates).trim());
        cellPos = new Vec3[cells];
        cellType = new int[cells];
        for (int k = 0; k < cells; k++) {
            String[] t = lines.get(2 + gates + k).trim().split(" ");
            cellPos[k] = new Vec3(Double.parseDouble(t[0]), Double.parseDouble(t[1]), Double.parseDouble(t[2]));
            cellType[k] = t[3].equals("CHARGE") ? Rules.CHARGE : t[3].equals("SHIELD") ? Rules.SHIELD : Rules.GHOST;
        }
    }

    public String turn(List<String> lines) {
        double[] s = Greedy.nums(lines.get(me));
        Drone base = new Drone(0, new Vec3(s[0], s[1], s[2]), new Vec3(s[6], s[7], s[8]));
        base.v = new Vec3(s[3], s[4], s[5]);
        base.u = new Vec3(s[9], s[10], s[11]);
        if (s.length > 24) base.w = new Vec3(s[22], s[23], s[24]);
        base.nextGate = (int) s[12];
        base.lap = (int) s[13];
        base.boosts = (int) s[14];
        base.boostTimer = (int) s[15];
        base.battery = (int) s[16];
        base.cutout = (int) s[17];
        base.item = (int) s[21];
        base.mode = Command.ACRO;
        int[] timers = new int[cellPos.length];
        for (int k = 0; k < timers.length; k++) timers[k] = Integer.parseInt(lines.get(players + k).trim());

        List<double[]> cands = new ArrayList<>();
        for (double[] pr : params) {
            cands.add(new double[]{pr[0], pr[1], pr[2], pr[3], 0, -1});
            if (base.boosts > 0) cands.add(new double[]{pr[0], pr[1], pr[2], pr[3], 1, -1});
        }
        for (int k = 0; k < cellPos.length; k++) {
            if (timers[k] > 0 || (cellType[k] != Rules.CHARGE && base.item != 0)) continue;
            if (cellPos[k].sub(base.p).len() > 5000) continue;
            cands.add(new double[]{650, 0.5, 0.3, 72, 0, k});
            cands.add(new double[]{850, 0.5, 0.3, 80, 0, k});
        }
        double best = Double.NEGATIVE_INFINITY;
        int[] bestCmd = null;
        boolean bestBoost = false;
        double[] bestPr = null;
        for (double[] pr : cands) {
            double score = rollout(base, timers, pr);
            if (lastPick != null && same(pr, lastPick)) score += 150;
            if (score > best) {
                best = score;
                bestPr = pr;
                bestBoost = pr[4] == 1;
            }
        }
        lastPick = bestPr;
        bestCmd = firstCommand(base, bestPr);
        boolean use = base.item != 0 && threatened(lines, base);
        String cmd = bestCmd[0] + " " + bestCmd[1] + " " + bestCmd[2] + " " + bestCmd[3] + (bestBoost ? " BOOST" : "") + (use ? " USE" : "");
        if (first) { first = false; return "ACRO " + cmd + " CAM 40"; }
        return cmd;
    }

    private static boolean same(double[] a, double[] b) {
        for (int i = 0; i < 4; i++) if (a[i] != b[i]) return false;
        return a[5] == b[5];
    }

    private int[] firstCommand(Drone d, double[] pr) {
        Vec3[] cn = target(d, pr, cellTimersZero());
        return AcroControl.control(d.p, d.v, d.f, d.u, d.w, cn[0], cn[1], pr[0], pr[1], pr[2], pr[3]);
    }

    private int[] cellTimersZero() { return new int[cellPos.length]; }

    private Vec3[] target(Drone d, double[] pr, int[] timers) {
        int k = (int) pr[5];
        if (k >= 0 && timers[k] == 0) return new Vec3[]{cellPos[k], cellPos[k].sub(d.p).norm()};
        return new Vec3[]{track.c[d.nextGate], track.n[d.nextGate]};
    }

    private double rollout(Drone base, int[] timers, double[] pr) {
        Drone d = base.copy(0);
        Game g = new Game(solo, track, new Drone[]{d});
        g.pylons = pylons;
        g.cellPos = cellPos;
        g.cellType = cellType;
        g.cellTimer = timers.clone();
        Command[] cmds = new Command[1];
        int t = 0;
        for (; t < horizon && d.active(); t++) {
            boolean chase = pr[5] >= 0 && t < 30;
            Vec3[] cn = chase ? target(d, pr, g.cellTimer) : new Vec3[]{track.c[d.nextGate], track.n[d.nextGate]};
            int[] k = AcroControl.control(d.p, d.v, d.f, d.u, d.w, cn[0], cn[1], pr[0], pr[1], pr[2], pr[3]);
            cmds[0] = new Command(Command.ACRO, k[0], k[1], k[2], k[3], t == 0 && pr[4] == 1, "");
            g.step(cmds);
            if (d.lap >= laps) break;
        }
        double score = d.gatesCleared * 1e6 - g.distNext(d) + d.boosts * BOOST_VALUE + (d.item != 0 ? ITEM_VALUE : 0)
                + (d.shield > 0 || d.ghost > 0 ? ITEM_VALUE : 0);
        if (d.state == Drone.DESTROYED) score -= 1e9;
        if (d.lap >= laps) score += 1e8 - t * 1e4;
        return score;
    }

    private boolean threatened(List<String> lines, Drone me0) {
        for (int j = 0; j < players; j++) {
            if (j == me) continue;
            double[] o = Greedy.nums(lines.get(j));
            if (o[18] != 1) continue;
            Vec3 op = new Vec3(o[0], o[1], o[2]), ov = new Vec3(o[3], o[4], o[5]);
            Vec3 rel = op.sub(me0.p);
            double closing = -rel.dot(ov.sub(me0.v)) / Math.max(1, rel.len());
            if (rel.len() < 1500 && closing > Rules.CUTOUT_SPEED * 0.6) return true;
        }
        return false;
    }
}

final class Stdin {
    public static void main(String[] args) throws Exception {
        run(args[0].equals("greedy") ? new Greedy() : args[0].equals("plannerx") ? new PlannerX() : args[0].equals("acro") ? new AcroPlanner() : new Planner());
    }

    public static void run(Bot bot) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String head = in.readLine();
        String[] h = head.trim().split(" ");
        int players = Integer.parseInt(h[0]), gates = Integer.parseInt(h[3]);
        List<String> init = new ArrayList<>();
        init.add(head);
        for (int i = 0; i < gates; i++) init.add(in.readLine());
        String cl = in.readLine();
        init.add(cl);
        int cells = Integer.parseInt(cl.trim());
        for (int i = 0; i < cells; i++) init.add(in.readLine());
        String pl = in.readLine();
        init.add(pl);
        int pylons = Integer.parseInt(pl.trim());
        for (int i = 0; i < pylons; i++) init.add(in.readLine());
        bot.init(init);
        while (true) {
            List<String> lines = new ArrayList<>();
            if (in.readLine() == null) return;
            for (int i = 0; i < players + cells; i++) {
                String l = in.readLine();
                if (l == null) return;
                lines.add(l);
            }
            System.out.println(bot.turn(lines));
            System.out.flush();
        }
    }
}

5.aiCode:
use std::io::{self, BufRead, Write};
use std::time::Instant;

const G: f64 = 20.0;
const THRUST: f64 = 50.0;
const DRAG: f64 = 0.97;
const BOOST: f64 = 300.0;
const R: f64 = 200.0;
const AX: f64 = 12000.0;
const AY: f64 = 12000.0;
const AZ: f64 = 5000.0;
const LAND: f64 = 150.0;
const RESTART: f64 = 300.0;
const RECHARGE: i32 = 40;
const SPIN_UP: f64 = 0.4;
const CRASH_SPEED: f64 = 250.0;
const CUTOUT_TURNS: i32 = 8;
const NI: usize = 42;
const NH: usize = 64;
const NO: usize = 2;
const PO: usize = 4;
const WEIGHTS: &str = "";
const PWEIGHTS: &str = "";

#[derive(Clone, Copy, Debug)]
struct V(f64, f64, f64);

impl V {
    fn add(self, o: V) -> V { V(self.0 + o.0, self.1 + o.1, self.2 + o.2) }
    fn sub(self, o: V) -> V { V(self.0 - o.0, self.1 - o.1, self.2 - o.2) }
    fn mul(self, k: f64) -> V { V(self.0 * k, self.1 * k, self.2 * k) }
    fn dot(self, o: V) -> f64 { self.0 * o.0 + self.1 * o.1 + self.2 * o.2 }
    fn cross(self, o: V) -> V { V(self.1 * o.2 - self.2 * o.1, self.2 * o.0 - self.0 * o.2, self.0 * o.1 - self.1 * o.0) }
    fn len(self) -> f64 { self.dot(self).sqrt() }
    fn norm(self) -> V { let l = self.len(); if l == 0.0 { self } else { self.mul(1.0 / l) } }
    fn rot(self, k: V, a: f64) -> V {
        let (s, c) = a.sin_cos();
        self.mul(c).add(k.cross(self).mul(s)).add(k.mul(k.dot(self) * (1.0 - c)))
    }
    fn round(self, s: f64) -> V { V(rd(self.0, s), rd(self.1, s), rd(self.2, s)) }
}

fn rd(v: f64, s: f64) -> f64 { (v * s + 0.5).floor() / s }

#[derive(Clone, Copy)]
struct Cmd { t: i32, y: i32, p: i32, r: i32, boost: bool }

#[derive(Clone)]
struct S {
    p: V, v: V, f: V, u: V, w: V,
    next: usize, cleared: i32, lap: i32,
    boosts: i32, max_boosts: i32, boost_timer: i32,
    battery: i32, cutout: i32, dead: bool, done: bool,
}

struct Track { c: Vec<V>, n: Vec<V>, laps: i32, clear: f64, py: Vec<(f64, f64, f64)> }

struct Other { p: V, v: V, ghost: i32 }

struct Layer { w: Vec<f32>, b: Vec<f32>, i: usize, o: usize }

struct Net { l: Vec<Layer> }

fn b64(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let (mut acc, mut bits) = (0u32, 0);
    for ch in s.bytes() {
        let v = match ch { b'A'..=b'Z' => ch - b'A', b'a'..=b'z' => ch - b'a' + 26, b'0'..=b'9' => ch - b'0' + 52, b'+' => 62, b'/' => 63, _ => continue } as u32;
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 { bits -= 8; out.push((acc >> bits) as u8 & 255); }
    }
    out
}

impl Net {
    fn load(blob: &[u8], dims: &[usize]) -> Net {
        let mut pos = 0;
        let mut rd = |n: usize| -> Vec<f32> {
            let sc = f32::from_le_bytes([blob[pos], blob[pos + 1], blob[pos + 2], blob[pos + 3]]);
            pos += 4;
            let v = (0..n).map(|k| i16::from_le_bytes([blob[pos + 2 * k], blob[pos + 2 * k + 1]]) as f32 * sc).collect();
            pos += 2 * n;
            v
        };
        let mut l = Vec::new();
        for k in 0..dims.len() - 1 {
            let (i, o) = (dims[k], dims[k + 1]);
            let w = rd(i * o);
            let b = rd(o);
            l.push(Layer { w, b, i, o });
        }
        Net { l }
    }
    fn run(&self, x: &[f32], out: &mut [f32]) {
        let mut a = [0f32; 64];
        let mut b = [0f32; 64];
        a[..x.len()].copy_from_slice(x);
        let n = self.l.len();
        for (k, ly) in self.l.iter().enumerate() {
            for o in 0..ly.o {
                let row = &ly.w[o * ly.i..(o + 1) * ly.i];
                let mut s = ly.b[o];
                for i in 0..ly.i { s += row[i] * a[i]; }
                b[o] = if k + 1 < n { s.max(0.0) } else { s };
            }
            a[..ly.o].copy_from_slice(&b[..ly.o]);
        }
        out.copy_from_slice(&a[..out.len()]);
    }
}

fn feats(s: &S, tr: &Track, x: &mut [f32; NI]) {
    let m = tr.c.len();
    let (c0, n0) = (tr.c[s.next], tr.n[s.next]);
    let h = V(n0.0, n0.1, 0.0);
    let ex = if h.len() < 1e-6 { V(1.0, 0.0, 0.0) } else { h.norm() };
    let ey = V(-ex.1, ex.0, 0.0);
    let fr = |v: V| (v.dot(ex) as f32, v.dot(ey) as f32, v.2 as f32);
    let mut k = 0;
    let mut put = |x: &mut [f32; NI], t: (f32, f32, f32), sc: f32| { x[k] = t.0 * sc; x[k + 1] = t.1 * sc; x[k + 2] = t.2 * sc; k += 3; };
    put(x, fr(s.p.sub(c0)), 1.0 / 3000.0);
    put(x, fr(s.v), 1.0 / 300.0);
    put(x, fr(s.f), 1.0);
    put(x, fr(s.u), 1.0);
    put(x, fr(n0), 1.0);
    let g1 = (s.next + 1) % m;
    let g2 = (s.next + 2) % m;
    put(x, fr(tr.c[g1].sub(c0)), 1.0 / 3000.0);
    put(x, fr(tr.n[g1]), 1.0);
    put(x, fr(tr.c[g2].sub(c0)), 1.0 / 3000.0);
    put(x, fr(tr.n[g2]), 1.0);
    x[27] = (s.p.2 / 1000.0) as f32;
    x[28] = s.battery as f32 / 100.0;
    x[29] = s.boosts as f32 / 3.0;
    x[30] = s.boost_timer as f32 / 40.0;
    x[31] = s.cutout as f32 / 8.0;
    let mut best = [(1e18, 5.0f32, 5.0f32, 0.0f32); 2];
    for &(px, py, pr) in &tr.py {
        let d = V(px - s.p.0, py - s.p.1, 0.0);
        let dd = d.len();
        let e = (dd, (d.dot(ex) / 3000.0) as f32, (d.dot(ey) / 3000.0) as f32, (pr / 400.0) as f32);
        if dd < best[0].0 { best[1] = best[0]; best[0] = e; } else if dd < best[1].0 { best[1] = e; }
    }
    for j in 0..2 { x[32 + 3 * j] = best[j].1; x[33 + 3 * j] = best[j].2; x[34 + 3 * j] = best[j].3; }
    x[38] = (s.p.0 / 6000.0 - 1.0) as f32;
    x[39] = (s.p.1 / 6000.0 - 1.0) as f32;
    x[40] = (route_dist(s, tr) / 3000.0) as f32;
    let target = if s.p.sub(c0).dot(n0) < 0.0 { c0 } else { c0.sub(n0.mul(1200.0)) };
    x[41] = (s.v.dot(target.sub(s.p).norm()) / 300.0) as f32;
}

fn step(s: &mut S, k: &Cmd, tr: &Track) {
    s.f = s.f.norm();
    s.u = s.u.sub(s.f.mul(s.u.dot(s.f))).norm();
    if s.cutout > 0 && s.p.2 - R <= RESTART { s.cutout = 0; }
    let off = s.cutout > 0 || s.battery <= 0;
    let mut thrust = 0.0;
    if off {
        s.w = V(0.0, 0.0, 0.0);
        if s.cutout > 0 { s.cutout -= 1; }
    } else {
        let rate = 60f64.to_radians();
        let r = s.f.cross(s.u);
        let w = r.mul(-(k.p as f64) / 100.0 * rate).add(s.f.mul(k.r as f64 / 100.0 * rate)).add(s.u.mul(-(k.y as f64) / 100.0 * rate));
        s.w = s.w.add(w.sub(s.w).mul(SPIN_UP));
        let ws = s.w;
        spin(s, ws);
        thrust = k.t as f64 / 100.0 * THRUST;
        if k.boost && s.boosts > 0 {
            s.v = s.v.add(s.u.mul(BOOST));
            if s.boosts == s.max_boosts { s.boost_timer = RECHARGE; }
            s.boosts -= 1;
        }
    }
    s.v = s.v.add(s.u.mul(thrust)).add(V(0.0, 0.0, -G));
    let mut t = 0.0;
    let mut cleared = false;
    for _ in 0..16 {
        if t >= 1.0 || s.dead || s.done { break; }
        let mut best = 1.0 - t;
        let mut kind = -1;
        let cand = [
            if s.v.2 < 0.0 { (s.p.2 - R) / -s.v.2 } else { 2.0 },
            if s.v.0 < 0.0 { (s.p.0 - R) / -s.v.0 } else if s.v.0 > 0.0 { (AX - R - s.p.0) / s.v.0 } else { 2.0 },
            if s.v.1 < 0.0 { (s.p.1 - R) / -s.v.1 } else if s.v.1 > 0.0 { (AY - R - s.p.1) / s.v.1 } else { 2.0 },
            if s.v.2 > 0.0 { (AZ - R - s.p.2) / s.v.2 } else { 2.0 },
        ];
        for (i, &x) in cand.iter().enumerate() {
            let x = x.max(0.0);
            if x < best { best = x; kind = i as i32; }
        }
        for (k, &(px, py, pr)) in tr.py.iter().enumerate() {
            let (qx, qy) = (s.p.0 - px, s.p.1 - py);
            let bq = qx * s.v.0 + qy * s.v.1;
            if bq >= 0.0 { continue; }
            let rr = pr + R;
            let aq = s.v.0 * s.v.0 + s.v.1 * s.v.1;
            let cq = qx * qx + qy * qy - rr * rr;
            let x = if cq <= 0.0 { 0.0 } else {
                let disc = bq * bq - aq * cq;
                if disc < 0.0 { continue; }
                (-bq - disc.sqrt()) / aq
            };
            if x < best { best = x; kind = 4 + k as i32; }
        }
        let p0 = s.p;
        s.p = s.p.add(s.v.mul(best));
        cleared |= gate(s, p0, tr);
        t += best;
        match kind {
            0 => {
                s.p = V(s.p.0, s.p.1, R);
                if off || s.cutout > 0 || -s.v.2 > LAND { s.dead = true; s.v = V(0.0, 0.0, 0.0); } else { s.v = V(s.v.0, s.v.1, 0.0); }
            }
            1 => s.v = V(-s.v.0, s.v.1, s.v.2),
            2 => s.v = V(s.v.0, -s.v.1, s.v.2),
            3 => s.v = V(s.v.0, s.v.1, -s.v.2),
            k if k >= 4 => {
                let (px, py, _) = tr.py[(k - 4) as usize];
                let n = V(s.p.0 - px, s.p.1 - py, 0.0).norm();
                let hit = -s.v.dot(n);
                s.v = s.v.add(n.mul(2.0 * hit));
                if hit >= CRASH_SPEED { s.cutout = CUTOUT_TURNS; }
            }
            _ => break,
        }
    }
    if s.dead { return; }
    s.v = s.v.mul(DRAG).round(100.0);
    s.p = s.p.round(100.0);
    s.f = s.f.round(1e6);
    s.u = s.u.round(1e6);
    s.w = s.w.round(1e6);
    if s.boosts < s.max_boosts {
        s.boost_timer -= 1;
        if s.boost_timer <= 0 {
            s.boosts += 1;
            s.boost_timer = if s.boosts < s.max_boosts { RECHARGE } else { 0 };
        }
    }
    s.battery = if cleared { 100 } else { (s.battery - 1).max(0) };
}

fn spin(s: &mut S, w: V) {
    let a = w.len();
    if a == 0.0 { return; }
    let k = w.mul(1.0 / a);
    s.f = s.f.rot(k, a);
    s.u = s.u.rot(k, a);
}

fn gate(s: &mut S, p0: V, tr: &Track) -> bool {
    let g = s.next;
    let (c, n) = (tr.c[g], tr.n[g]);
    let d0 = n.dot(p0.sub(c));
    let d1 = n.dot(s.p.sub(c));
    if !(d0 < 0.0 && d1 >= 0.0) { return false; }
    let x = p0.add(s.p.sub(p0).mul(d0 / (d0 - d1)));
    if x.sub(c).len() >= tr.clear { return false; }
    s.cleared += 1;
    s.next = (g + 1) % tr.c.len();
    if g == 0 {
        s.lap += 1;
        if s.lap >= tr.laps { s.done = true; }
    }
    true
}

fn route_dist(s: &S, tr: &Track) -> f64 {
    let (c, n) = (tr.c[s.next], tr.n[s.next]);
    let rel = s.p.sub(c);
    let along = rel.dot(n);
    let lat = rel.sub(n.mul(along)).len();
    if along < 0.0 && lat < 250.0 + (-along) * 1.0 { rel.len() } else { s.p.sub(c.sub(n.mul(1200.0))).len() + 1200.0 }
}

struct Ctx<'a> { tr: &'a Track, others: &'a [Other], my_ghost: i32, net: Option<&'a Net>, goal: i32, h: usize, hyb: f64, early: f64, wt: [f64; 3] }

fn evaluate(s0: &S, plan: &[Cmd], cx: &Ctx) -> f64 {
    let mut s = s0.clone();
    let mut risk = 0.0;
    let mut early = 0.0;
    for (i, k) in plan.iter().take(cx.h).enumerate() {
        let before = s.cleared;
        step(&mut s, k, cx.tr);
        if s.cleared > before { early += (cx.h - i) as f64; }
        if s.dead { return -1e9 + s.cleared as f64 * 1e5 + i as f64 * 100.0; }
        if s.done { return 1e9 - i as f64 * 1e4 - risk; }
        if i < 25 {
            let tt = (i + 1) as f64;
            for o in cx.others {
                if (o.ghost as f64) > tt || (cx.my_ghost as f64) > tt { continue; }
                let op = o.p.add(o.v.mul(tt));
                let d = s.p.sub(op);
                let dist = d.len();
                if dist < 450.0 {
                    let closing = -d.dot(s.v.sub(o.v)) / dist.max(1.0);
                    let w = 1.0 - i as f64 / 25.0;
                    risk += if closing > 220.0 { 2.5e5 * w } else { 2e4 * w };
                }
            }
        }
        if cx.net.is_some() && cx.hyb == 0.0 && s.cleared >= cx.goal { return -((i + 1) as f64) * 5000.0 - risk; }
    }
    if let (Some(net), true) = (cx.net, cx.hyb == 0.0) {
        let mut x = [0f32; NI];
        feats(&s, cx.tr, &mut x);
        let mut o = [0f32; NO];
        net.run(&x, &mut o);
        let rem = ((cx.goal - s.cleared).clamp(1, NO as i32) - 1) as usize;
        return -(cx.h as f64 + o[rem] as f64 * 20.0) * 5000.0 - risk;
    }
    let (c, n) = (cx.tr.c[s.next], cx.tr.n[s.next]);
    let target = if s.p.sub(c).dot(n) < 0.0 { c } else { c.sub(n.mul(1200.0)) };
    let toward = s.v.dot(target.sub(s.p).norm());
    let mut extra = 0.0;
    if let Some(net) = cx.net {
        let mut x = [0f32; NI];
        feats(&s, cx.tr, &mut x);
        let mut o = [0f32; NO];
        net.run(&x, &mut o);
        extra = -cx.hyb * o[0] as f64 * 20.0;
    }
    s.cleared as f64 * 1e5 - route_dist(&s, cx.tr) + toward * cx.wt[0] + s.boosts as f64 * cx.wt[1] + (s.p.2.min(600.0)) * cx.wt[2] - risk + extra + cx.early * early
}

fn heuristic(s0: &S, tr: &Track, h: usize, cruise: f64, lead: f64, tilt: f64, gain: f64, boost_at: i32) -> Vec<Cmd> {
    let mut s = s0.clone();
    let mut out = Vec::with_capacity(h);
    for i in 0..h {
        let (c, n) = (tr.c[s.next], tr.n[s.next]);
        let mut k = control(&s, c, n, cruise, gain, lead, tilt);
        k.boost = i as i32 == boost_at;
        out.push(k);
        step(&mut s, &k, tr);
        if s.dead || s.done {
            while out.len() < h { out.push(k); }
            break;
        }
    }
    out
}

fn policy_plan(s0: &S, tr: &Track, h: usize, pn: &Net, rng: &mut Rng, noise: i32) -> Vec<Cmd> {
    let mut s = s0.clone();
    let mut out = Vec::with_capacity(h);
    let mut x = [0f32; NI];
    let mut o = [0f32; PO];
    for _ in 0..h {
        feats(&s, tr, &mut x);
        pn.run(&x, &mut o);
        let j = |v: f32, lo: i32, rng: &mut Rng| ((v * 100.0).round() as i32 + if noise > 0 { rng.range(-noise, noise) } else { 0 }).clamp(lo, 100);
        let k = Cmd { t: j(o[0], 0, rng), y: j(o[1], -100, rng), p: j(o[2], -100, rng), r: j(o[3], -100, rng), boost: false };
        out.push(k);
        step(&mut s, &k, tr);
        if s.dead || s.done {
            while out.len() < h { out.push(k); }
            break;
        }
    }
    out
}

fn control(s: &S, c: V, n: V, cruise: f64, gain: f64, lead: f64, tilt: f64) -> Cmd {
    let f = s.f.norm();
    let u = s.u.sub(f.mul(s.u.dot(f))).norm();
    let p = s.p;
    let along = p.sub(c).dot(n);
    let lat = p.sub(c).sub(n.mul(along));
    let lat_len = lat.len();
    let cone = along < 0.0 && lat_len < -along * 1.2 + 300.0;
    let aim = if cone { c.add(n.mul(along * lead + 200.0)) } else { c.add(n.mul(-(1200f64.max(lat_len)))).add(lat.norm().mul(lat_len.min(700.0))) };
    let dist = aim.sub(p).len();
    let speed = if cone { cruise } else { cruise.min((60.0 * dist).sqrt() + 60.0) };
    let dir = aim.sub(p).norm();
    let mut vd = dir.mul(speed);
    let floor_v = -(p.2 - 350.0) * 0.25;
    if vd.2 < floor_v { vd.2 = floor_v; }
    let a = vd.sub(s.v).mul(gain);
    let az = (a.2 + G).max(1.0);
    let h = a.0.hypot(a.1);
    let limit = az * tilt.to_radians().tan();
    let (mut ax, mut ay) = (a.0, a.1);
    if h > limit { ax *= limit / h; ay *= limit / h; }
    let acc = V(ax, ay, az);
    let ut = acc.norm();
    let mut heading = V(dir.0, dir.1, 0.0);
    if heading.len() < 1e-6 { heading = V(f.0, f.1, 0.0); }
    let mut ft = heading.sub(ut.mul(heading.dot(ut)));
    if ft.len() < 1e-6 { ft = f.sub(ut.mul(f.dot(ut))); }
    let ft = ft.norm();
    let mut want = rotation(f, u, ft, ut).mul(1.2);
    let rate = 60f64.to_radians();
    if want.len() > rate { want = want.mul(rate / want.len()); }
    let w = s.w.add(want.sub(s.w).mul(1.8));
    let r = f.cross(u);
    let rate = 60f64.to_radians();
    let cl = |x: f64| (x.round() as i32).clamp(-100, 100);
    let tilt_err = u.dot(ut).clamp(-1.0, 1.0).acos();
    let thrust = acc.len() * tilt_err.cos().max(0.0);
    Cmd { t: ((thrust / THRUST * 100.0).round() as i32).clamp(0, 100), y: cl(-w.dot(u) / rate * 100.0), p: cl(-w.dot(r) / rate * 100.0), r: cl(w.dot(f) / rate * 100.0), boost: false }
}

fn quat(f: V, u: V) -> [f64; 4] {
    let l = u.cross(f);
    let (m00, m01, m02, m10, m11, m12, m20, m21, m22) = (f.0, l.0, u.0, f.1, l.1, u.1, f.2, l.2, u.2);
    let tr = m00 + m11 + m22;
    if tr > 0.0 {
        let s = (tr + 1.0).sqrt() * 2.0;
        [s / 4.0, (m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s]
    } else if m00 > m11 && m00 > m22 {
        let s = (1.0 + m00 - m11 - m22).sqrt() * 2.0;
        [(m21 - m12) / s, s / 4.0, (m01 + m10) / s, (m02 + m20) / s]
    } else if m11 > m22 {
        let s = (1.0 + m11 - m00 - m22).sqrt() * 2.0;
        [(m02 - m20) / s, (m01 + m10) / s, s / 4.0, (m12 + m21) / s]
    } else {
        let s = (1.0 + m22 - m00 - m11).sqrt() * 2.0;
        [(m10 - m01) / s, (m02 + m20) / s, (m12 + m21) / s, s / 4.0]
    }
}

fn rotation(f: V, u: V, ft: V, ut: V) -> V {
    let qc = quat(f, u);
    let qt = quat(ft, ut);
    let mut w = qt[0] * qc[0] + qt[1] * qc[1] + qt[2] * qc[2] + qt[3] * qc[3];
    let mut x = -qt[0] * qc[1] + qt[1] * qc[0] - qt[2] * qc[3] + qt[3] * qc[2];
    let mut y = -qt[0] * qc[2] + qt[1] * qc[3] + qt[2] * qc[0] - qt[3] * qc[1];
    let mut z = -qt[0] * qc[3] - qt[1] * qc[2] + qt[2] * qc[1] + qt[3] * qc[0];
    if w < 0.0 { w = -w; x = -x; y = -y; z = -z; }
    let s = (x * x + y * y + z * z).sqrt();
    if s == 0.0 { return V(0.0, 0.0, 0.0); }
    let a = 2.0 * s.atan2(w);
    V(x, y, z).mul(a / s)
}

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn below(&mut self, n: u64) -> u64 { self.next() % n }
    fn range(&mut self, lo: i32, hi: i32) -> i32 { lo + self.below((hi - lo + 1) as u64) as i32 }
}

fn mutate(plan: &mut [Cmd], rng: &mut Rng, h: usize) {
    let start = (rng.below(h as u64) as f64 * (rng.below(1000) as f64 / 1000.0)) as usize;
    let len = 1 + rng.below(12) as usize;
    let end = (start + len).min(h);
    match rng.below(5) {
        0 => {
            let k = Cmd { t: rng.range(0, 100), y: rng.range(-100, 100), p: rng.range(-100, 100), r: rng.range(-100, 100), boost: false };
            for i in start..end { let b = plan[i].boost; plan[i] = k; plan[i].boost = b; }
        }
        1 => {
            let (dt, dy, dp, dr) = (rng.range(-30, 30), rng.range(-40, 40), rng.range(-40, 40), rng.range(-40, 40));
            for i in start..end {
                plan[i].t = (plan[i].t + dt).clamp(0, 100);
                plan[i].y = (plan[i].y + dy).clamp(-100, 100);
                plan[i].p = (plan[i].p + dp).clamp(-100, 100);
                plan[i].r = (plan[i].r + dr).clamp(-100, 100);
            }
        }
        2 => { let i = start.min(h - 1); plan[i].boost = !plan[i].boost; }
        3 => { for i in start..end { plan[i].t = if rng.below(2) == 0 { 100 } else { 0 }; } }
        _ => { let pr = rng.range(-100, 100); for i in start..end { plan[i].p = pr; } }
    }
}

fn nums(line: &str) -> Vec<f64> { line.split_whitespace().map(|x| x.parse().unwrap_or(0.0)).collect() }

fn env_f(k: &str, d: f64) -> f64 { std::env::var(k).ok().and_then(|x| x.parse().ok()).unwrap_or(d) }

fn refeat(path: &str) {
    let txt = std::fs::read_to_string(path).unwrap();
    let mut tr = Track { c: Vec::new(), n: Vec::new(), laps: 3, clear: 300.0, py: Vec::new() };
    let out = io::stdout();
    let mut o = out.lock();
    let wsrc = std::env::var("WFILE").ok().map(|f| std::fs::read_to_string(f).unwrap()).unwrap_or(WEIGHTS.to_string());
    let net = if wsrc.trim().is_empty() { None } else { Some(Net::load(&b64(&wsrc), &[NI, NH, NH, NO])) };
    for line in txt.lines() {
        let (a, b) = line.split_once('|').unwrap_or((line, ""));
        let t: Vec<&str> = a.split_whitespace().collect();
        let v: Vec<f64> = t.iter().skip(1).map(|x| x.parse().unwrap_or(0.0)).collect();
        match t.first().copied() {
            Some("TRK") => { tr.laps = v[0] as i32; tr.clear = v[1]; }
            Some("G") => { tr.c.push(V(v[0], v[1], v[2])); tr.n.push(V(v[3], v[4], v[5])); }
            Some("P") => tr.py.push((v[0], v[1], v[2])),
            Some("FIN") => writeln!(o, "{}", line).unwrap(),
            Some("S") => {
                let s = S { p: V(v[3], v[4], v[5]), v: V(v[6], v[7], v[8]), f: V(v[9], v[10], v[11]), u: V(v[12], v[13], v[14]), w: V(0.0, 0.0, 0.0),
                    next: v[15] as usize, cleared: 0, lap: v[16] as i32, boosts: v[17] as i32, max_boosts: v[18] as i32, boost_timer: v[19] as i32,
                    battery: v[20] as i32, cutout: v[21] as i32, dead: false, done: false };
                let mut x = [0f32; NI];
                feats(&s, &tr, &mut x);
                let xs: Vec<String> = x.iter().map(|q| format!("{:.4}", q)).collect();
                let mut pr = [0f32; NO];
                if let Some(nt) = net.as_ref() { nt.run(&x, &mut pr); }
                writeln!(o, "T {} {} {} {} |{} => {} {}", v[0], v[1], v[2], xs.join(" "), b, pr[0] * 20.0, pr[1] * 20.0).unwrap();
            }
            _ => {}
        }
    }
}

fn oeval(s0: &S, plan: &[Cmd], tr: &Track, k: i32) -> (f64, [i32; 2]) {
    let mut s = s0.clone();
    let mut at = [-1; 2];
    for (i, c) in plan.iter().enumerate() {
        let before = s.cleared;
        step(&mut s, c, tr);
        if s.cleared > before && (before as usize) < 2 { at[before as usize] = i as i32 + 1; }
        if s.dead { return (-1e9 + s.cleared as f64 * 1e5 + i as f64 * 100.0, at); }
        if s.cleared >= k || s.done { return (1e9 - i as f64 * 1e4, at); }
    }
    let (c, n) = (tr.c[s.next], tr.n[s.next]);
    let target = if s.p.sub(c).dot(n) < 0.0 { c } else { c.sub(n.mul(1200.0)) };
    let toward = s.v.dot(target.sub(s.p).norm());
    (s.cleared as f64 * 1e5 - route_dist(&s, tr) + toward * 3.0 + s.boosts as f64 * 800.0 + (s.p.2.min(600.0)) * 0.5, at)
}

fn solve(s0: &S, tr: &Track, k: i32, evals: usize, rng: &mut Rng) -> [i32; 2] {
    let h = 100;
    let mut cur = heuristic(s0, tr, h, 650.0, 0.3, 72.0, 0.4, -1);
    let mut cs = oeval(s0, &cur, tr, k);
    for &cruise in &[500.0, 650.0, 850.0, 1000.0] { for &lead in &[0.3, 0.5] { for &tilt in &[60.0, 72.0, 80.0, 89.0] { for &gain in &[0.3, 0.4, 0.6] {
        for &b in &[-1, 0] {
            if b == 0 && s0.boosts == 0 { continue; }
            let plan = heuristic(s0, tr, h, cruise, lead, tilt, gain, b);
            let sc = oeval(s0, &plan, tr, k);
            if sc.0 > cs.0 { cur = plan; cs = sc; }
        }
    } } } }
    for _ in 0..evals {
        let mut cand = cur.clone();
        mutate(&mut cand, rng, h);
        if rng.below(3) == 0 { mutate(&mut cand, rng, h); }
        let sc = oeval(s0, &cand, tr, k);
        if sc.0 >= cs.0 { cur = cand; cs = sc; }
    }
    cs.1
}

fn oracle(path: &str) {
    let txt = std::fs::read_to_string(path).unwrap();
    let evals = env_f("OEVALS", 20000.0) as usize;
    let every = env_f("OEVERY", 3.0) as i32;
    let pert = env_f("OPERT", 1.0) > 0.0;
    let mut tr = Track { c: Vec::new(), n: Vec::new(), laps: 3, clear: 300.0, py: Vec::new() };
    let mut rng = Rng(0x1234567 ^ std::process::id() as u64);
    let out = io::stdout();
    let mut o = out.lock();
    for line in txt.lines() {
        let a = line.split('|').next().unwrap();
        let t: Vec<&str> = a.split_whitespace().collect();
        let v: Vec<f64> = t.iter().skip(1).map(|x| x.parse().unwrap_or(0.0)).collect();
        match t.first().copied() {
            Some("TRK") => { tr.laps = v[0] as i32; tr.clear = v[1]; writeln!(o, "{}", line).unwrap(); }
            Some("G") | Some("P") => {
                if t[0] == "G" { tr.c.push(V(v[0], v[1], v[2])); tr.n.push(V(v[3], v[4], v[5])); } else { tr.py.push((v[0], v[1], v[2])); }
                writeln!(o, "{}", line).unwrap();
            }
            Some("S") => {
                if (v[0] as i32) % every != 0 || v[21] > 0.0 { continue; }
                let base = S { p: V(v[3], v[4], v[5]), v: V(v[6], v[7], v[8]), f: V(v[9], v[10], v[11]), u: V(v[12], v[13], v[14]), w: V(0.0, 0.0, 0.0),
                    next: v[15] as usize, cleared: 0, lap: v[16] as i32, boosts: v[17] as i32, max_boosts: v[18] as i32, boost_timer: v[19] as i32,
                    battery: v[20] as i32, cutout: v[21] as i32, dead: false, done: false };
                let remaining = tr.laps * tr.c.len() as i32 - v[1] as i32;
                let k = remaining.clamp(1, 2);
                for variant in 0..if pert { 2 } else { 1 } {
                    let mut s = base.clone();
                    if variant == 1 {
                        let u = |rng: &mut Rng, a: i32| rng.range(-a, a) as f64;
                        s.p = V((s.p.0 + u(&mut rng, 500)).clamp(300.0, AX - 300.0), (s.p.1 + u(&mut rng, 500)).clamp(300.0, AY - 300.0), (s.p.2 + u(&mut rng, 300)).clamp(300.0, AZ - 300.0)).round(100.0);
                        s.v = V(s.v.0 + u(&mut rng, 200), s.v.1 + u(&mut rng, 200), s.v.2 + u(&mut rng, 120)).round(100.0);
                        let ax = V(u(&mut rng, 100), u(&mut rng, 100), u(&mut rng, 100)).norm();
                        let ang = u(&mut rng, 45).to_radians();
                        s.f = s.f.rot(ax, ang).norm().round(1e6);
                        s.u = s.u.rot(ax, ang).norm().round(1e6);
                        s.battery = (s.battery - rng.range(0, 30)).max(5);
                    }
                    let at = solve(&s, &tr, k, evals, &mut rng);
                    writeln!(o, "S {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} | {} {}", v[0], v[1], variant,
                        s.p.0, s.p.1, s.p.2, s.v.0, s.v.1, s.v.2, s.f.0, s.f.1, s.f.2, s.u.0, s.u.1, s.u.2,
                        s.next, s.lap, s.boosts, s.max_boosts, s.boost_timer, s.battery, s.cutout, at[0], at[1]).unwrap();
                }
            }
            _ => {}
        }
    }
}

fn main() {
    if let Ok(p) = std::env::var("ORACLE") { oracle(&p); return; }
    if let Ok(p) = std::env::var("REFEAT") { refeat(&p); return; }
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let mut rl = || lines.next().unwrap().unwrap();
    let hd = nums(&rl());
    let (players, me, laps, gates) = (hd[0] as usize, hd[1] as usize, hd[2] as i32, hd[3] as usize);
    let mut c = Vec::new();
    let mut n = Vec::new();
    let mut clear = 300.0;
    for _ in 0..gates {
        let t = nums(&rl());
        c.push(V(t[0], t[1], t[2]));
        n.push(V(t[3], t[4], t[5]));
        clear = t[6] - R;
    }

    let rate = env_f("TOPGATE_RATE", 0.0);
    let cells: usize = rl().trim().parse().unwrap_or(0);
    for _ in 0..cells { rl(); }
    let pylons: usize = rl().trim().parse().unwrap_or(0);
    let mut py = Vec::new();
    for _ in 0..pylons { let t = nums(&rl()); py.push((t[0], t[1], t[2])); }
    let tr = Track { c, n, laps, clear, py };
    let wsrc = std::env::var("WFILE").ok().map(|f| std::fs::read_to_string(f).unwrap()).unwrap_or(WEIGHTS.to_string());
    let psrc = std::env::var("PFILE").ok().map(|f| std::fs::read_to_string(f).unwrap()).unwrap_or(PWEIGHTS.to_string());
    let use_v = env_f("USE_V", 1.0) > 0.0;
    let use_p = env_f("USE_P", 1.0) > 0.0;
    let net = if use_v && !wsrc.trim().is_empty() { Some(Net::load(&b64(&wsrc), &[NI, NH, NH, NO])) } else { None };
    let pnet = if use_p && !psrc.trim().is_empty() { Some(Net::load(&b64(&psrc), &[NI, NH, NH, PO])) } else { None };
    let hyb = env_f("HYB", 60.0);
    let h: usize = env_f("HOR", if net.is_some() && hyb == 0.0 { 40.0 } else { 15.0 }) as usize;
    let seeds_heur = env_f("HEUR", 1.0) > 0.0 || pnet.is_none();
    let explore = env_f("EXPLORE", 0.0);
    let mut dump = std::env::var("DUMP").ok().map(|d| std::fs::File::create(format!("{}/{}.txt", d, std::process::id())).unwrap());
    let budget_total = 28000.0 / players as f64 * 0.8;
    let mut used = 0.0;
    let mut turn = 0;
    let mut max_boosts = 0;
    let mut best: Vec<Cmd> = vec![Cmd { t: 60, y: 0, p: 0, r: 0, boost: false }; h];
    let mut rng = Rng(0x9E3779B97F4A7C15 ^ (me as u64 + 1));
    let mut xrng = Rng(0x2545F4914F6CDD1D ^ std::process::id() as u64);
    let out = io::stdout();
    loop {
        let remaining: f64 = rl().trim().parse().unwrap_or(0.0);
        let start = Instant::now();
        let mut rows = Vec::new();
        for _ in 0..players { rows.push(nums(&rl())); }
        for _ in 0..cells { rl(); }
        let m = &rows[me];
        if m[14] as i32 > max_boosts { max_boosts = m[14] as i32; }
        let s0 = S {
            p: V(m[0], m[1], m[2]), v: V(m[3], m[4], m[5]), f: V(m[6], m[7], m[8]), u: V(m[9], m[10], m[11]), w: V(m[22], m[23], m[24]),
            next: m[12] as usize, cleared: 0, lap: m[13] as i32, boosts: m[14] as i32, max_boosts, boost_timer: m[15] as i32,
            battery: m[16] as i32, cutout: m[17] as i32, dead: false, done: false,
        };
        let total_gates = laps * gates as i32;
        let done_gates = m[13] as i32 * gates as i32 + if m[12] as usize == 0 { gates as i32 - 1 } else { m[12] as i32 - 1 };
        let pace = if done_gates > 0 { (turn as f64 / done_gates as f64).max(18.0) } else { 25.0 };
        let left_turns = ((total_gates - done_gates).max(1) as f64 * pace * 1.1).max(60.0);
        let reserve = (600 - turn).max(0) as f64 * 2.0;
        let left = if rate > 0.0 { budget_total - used } else { remaining * 0.8 };
        let budget = ((left - reserve) / left_turns).clamp(1.0, 60.0) * if turn == 0 { 3.0 } else { 1.0 };
        let others: Vec<Other> = rows.iter().enumerate().filter(|(j, o)| *j != me && o[18] as i32 == 1)
            .map(|(_, o)| Other { p: V(o[0], o[1], o[2]), v: V(o[3], o[4], o[5]), ghost: o[20] as i32 }).collect();
        let cx = Ctx { tr: &tr, others: &others, my_ghost: m[20] as i32, net: net.as_ref(), goal: (total_gates - done_gates).clamp(1, NO as i32), h, hyb, early: env_f("EARLY", 300.0), wt: [env_f("TW", 3.0), env_f("BW", 800.0), env_f("ZW", 0.5)] };
        let mut shifted = best[1..].to_vec();
        shifted.push(best[h - 1]);
        for k in shifted.iter_mut() { k.boost = false; }
        for i in 0..h - 1 { shifted[i].boost = best[i + 1].boost; }
        let mut cur = shifted;
        let mut cur_score = evaluate(&s0, &cur, &cx);
        if seeds_heur {
            for &cruise in &[500.0, 650.0, 850.0, 1000.0] { for &lead in &[0.3, 0.5] { for &tilt in &[60.0, 72.0, 80.0, 89.0] { for &gain in &[0.3, 0.4, 0.6] {
                for &b in &[-1, 0] {
                    if b == 0 && s0.boosts == 0 { continue; }
                    let plan = heuristic(&s0, &tr, h, cruise, lead, tilt, gain, b);
                    let sc = evaluate(&s0, &plan, &cx);
                    if sc > cur_score { cur = plan; cur_score = sc; }
                }
            } } } }
        }
        if let Some(pn) = pnet.as_ref() {
            for j in 0..8 {
                let mut plan = policy_plan(&s0, &tr, h, pn, &mut rng, j * 6);
                if j % 2 == 1 && s0.boosts > 0 { plan[0].boost = true; }
                let sc = evaluate(&s0, &plan, &cx);
                if sc > cur_score { cur = plan; cur_score = sc; }
            }
        }
        let mut evals = 0;
        while if rate > 0.0 { (evals as f64) < budget * rate } else { start.elapsed().as_secs_f64() * 1000.0 < budget } {
            for _ in 0..8 {
                let mut cand = cur.clone();
                mutate(&mut cand, &mut rng, h);
                if rng.below(3) == 0 { mutate(&mut cand, &mut rng, h); }
                let sc = evaluate(&s0, &cand, &cx);
                evals += 1;
                if sc >= cur_score { cur = cand; cur_score = sc; }
            }
        }
        best = cur;
        let mut k = best[0];
        let mut flag = 0;
        if explore > 0.0 && (xrng.below(1_000_000) as f64) < explore * 1e6 {
            flag = 1;
            k.t = (k.t + xrng.range(-50, 50)).clamp(0, 100);
            k.y = (k.y + xrng.range(-60, 60)).clamp(-100, 100);
            k.p = (k.p + xrng.range(-60, 60)).clamp(-100, 100);
            k.r = (k.r + xrng.range(-60, 60)).clamp(-100, 100);
        }
        if let Some(f) = dump.as_mut() {
            if turn == 0 {
                writeln!(f, "TRK {} {} {} {}", tr.laps, tr.clear, tr.c.len(), tr.py.len()).unwrap();
                for g in 0..tr.c.len() { writeln!(f, "G {} {} {} {} {} {}", tr.c[g].0, tr.c[g].1, tr.c[g].2, tr.n[g].0, tr.n[g].1, tr.n[g].2).unwrap(); }
                for q in &tr.py { writeln!(f, "P {} {} {}", q.0, q.1, q.2).unwrap(); }
            }
            writeln!(f, "S {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} | {} {} {} {} {}", turn, done_gates, flag,
                s0.p.0, s0.p.1, s0.p.2, s0.v.0, s0.v.1, s0.v.2, s0.f.0, s0.f.1, s0.f.2, s0.u.0, s0.u.1, s0.u.2,
                s0.next, s0.lap, s0.boosts, s0.max_boosts, s0.boost_timer, s0.battery, s0.cutout, k.t, k.y, k.p, k.r, k.boost as i32).unwrap();
            let mut s1 = s0.clone();
            step(&mut s1, &k, &tr);
            if s1.done && players == 1 { writeln!(f, "FIN {}", turn + 1).unwrap(); }
        }
        let mut use_item = false;
        if m[21] as i32 != 0 {
            for (j, o) in rows.iter().enumerate() {
                if j == me || o[18] as i32 != 1 { continue; }
                let rel = V(o[0], o[1], o[2]).sub(s0.p);
                let closing = -rel.dot(V(o[3], o[4], o[5]).sub(s0.v)) / rel.len().max(1.0);
                if rel.len() < 1500.0 && closing > 150.0 { use_item = true; }
            }
        }
        let mut line = format!("{}{} {} {} {}", if turn == 0 { "ACRO " } else { "" }, k.t, k.y, k.p, k.r);
        if k.boost && s0.boosts > 0 { line.push_str(" BOOST"); }
        if use_item { line.push_str(" USE"); }
        if turn == 0 { line.push_str(" CAM 50"); }
        let ms = if rate > 0.0 { evals as f64 / rate } else { start.elapsed().as_secs_f64() * 1000.0 };
        used += ms;
        if std::env::var("MSG").is_ok() { line.push_str(&format!(" {}e {:.0}ms", evals, ms)); }
        eprintln!("turn {} evals {} ms {:.1} real {:.1} score {:.0} gate {} lap {} cut {} z {:.0} spd {:.0} bat {} state {} uz {:.2}", turn, evals, ms, start.elapsed().as_secs_f64() * 1000.0, cur_score, m[12], m[13], m[17], m[2], s0.v.len(), m[16], m[18], m[11]);
        let mut o = out.lock();
        writeln!(o, "{}", line).unwrap();
        o.flush().unwrap();
        turn += 1;
    }
}
